import os
import json
from taf.internal.robot_typecasts import time_to_seconds, to_boolean


class CommissioningInterface(object):

    def validate_scf(self, scf_file, skip_parameter_relation_errors=False, timeout=60):
        """Validate SCF.

        :param string scf_file: SCF file path
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param float timeout: Time to wait for positive procedure result
        
        """
        skip_parameter_relation_errors = to_boolean(skip_parameter_relation_errors)
        timeout = time_to_seconds(timeout)
        str(scf_file)

        parameters = {"skipParameterRelationErrors": skip_parameter_relation_errors}

        return self._api_client.execute_procedure("validateScf", parameters, timeout, input_file_name=scf_file)

    def migrate_scf(self, input_scf_file, output_scf_file, timeout=60):
        """Migrate SCF

        :param string input_scf_file: Input SCF file path
        :param string output_scf_file: Output SCF file path
        :param float timeout: Time to wait for positive procedure result
        
        """
        timeout = time_to_seconds(timeout)
        str(input_scf_file)
        str(output_scf_file)
        return self._api_client.execute_offline_procedure(
            "migrateScf", {}, timeout, input_file_name=input_scf_file, output_file_name=output_scf_file)

    def perform_commissioning(
            self, bts_id, scf_file, skip_parameter_relation_errors=False,
            should_activate=True, timeout=300, **kwargs):
        """Perform commissioning.

        :param string bts_id: BTS ID
        :param string scf_file: SCF file path
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param boolean should_activate: should automatically activate plan.
        :param float timeout: Time to wait for positive procedure result
        
        """
        should_activate = to_boolean(should_activate)
        skip_parameter_relation_errors = to_boolean(skip_parameter_relation_errors)
        timeout = time_to_seconds(timeout)
        str(bts_id)
        str(scf_file)

        parameters = {"btsId": bts_id, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True

        return self._api_client.execute_procedure("downloadPlan", parameters, timeout, input_file_name=scf_file)

    def perform_delta_recommissioning(self, delta_file, skip_parameter_relation_errors=False, should_activate=True, timeout=300):
        """Perform delta recommissioning.

        :param string delta_file: Delta JSON or path to JSON file.
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors.
        :param boolean should_activate: should automatically activate plan.
        :param float timeout: Time to wait for positive procedure result
        

        | Delta JSON is send to Admin API as "planObjects" parameter of "recomission" procedure.
        | For detailed instruction how to create delta JSON see Admin API doc:
        | http://cebula.emea.nsn-net.net:8888/spec/admin-spec/wikis/admin-api-recommissioning

        **SAMPLE DELTA:**

        ::

            [
                {
                    "distName": "MRBTS-1/LNBTS-1/LNMME-0",
                    "operation": "update",
                    "parameters": [
                        {
                            "parameterName": "ipAddrPrim",
                            "value": "10.0.1.99",
                            "operation": "update"
                        }
                    ]
                }
            ]
        """
        should_activate = to_boolean(should_activate)
        skip_parameter_relation_errors = to_boolean(skip_parameter_relation_errors)
        timeout = time_to_seconds(timeout)
        str(delta_file)

        if os.path.isfile(delta_file):
            with open(delta_file, 'r') as f:
                delta_file = f.read()

        delta = json.loads(delta_file)
        parameters = {"planObjects": delta, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True

        return self._api_client.execute_procedure("recommission", parameters, timeout)

    def perform_parameter_recommissioning(
            self, dist_name, parameter, operation, value, skip_parameter_relation_errors=False, should_activate=True, timeout=300):
        """Perform parameter recommissioning.

        :param string dist_name: Object dist name
        :param string parameter: Parameter name
        :param string operation: Parameter operation (create, update or delete)
        :param string value: Parameter value
        :param boolean skip_parameter_relation_errors: Skip parameter relation errors
        :param float timeout: Time to wait for positive procedure result
        
        """
        should_activate = to_boolean(should_activate)
        skip_parameter_relation_errors = to_boolean(skip_parameter_relation_errors)
        timeout = time_to_seconds(timeout)
        str(dist_name)
        str(parameter)
        assert operation in ("delete", "update", "create") and type(operation) is str

        parameters = {"distName": dist_name, "parameterName": parameter, "operation": operation, "value": value, "shouldBeActivated": should_activate}
        if skip_parameter_relation_errors:
            parameters["skipParameterRelationErrors"] = True
        return self._api_client.execute_procedure("setParameter", parameters, timeout)

    def activate_plan(self, plan_id, timeout=300):
        """Activate previously commissioned plan.commissioned

        :param string plan_id: Plan ID (delta dist name)
        :param float timeout: Time to wait for positive procedure result
        
        """
        timeout = time_to_seconds(timeout)
        str(plan_id)

        self._api_client.execute_procedure("activatePlan", {"deltaDN": plan_id}, timeout)

    def reset_configuration(self, remove_site_id, remove_security_credentials, timeout=500):
        """Reset configuration.

        :param boolean remove_site_id: Remove Site ID.
        :param boolean remove_security_credentials: Remove security credentials.
        :param float timeout: Time to wait for positive procedure result.
        
        """
        remove_site_id = to_boolean(remove_site_id)
        remove_security_credentials = to_boolean(remove_security_credentials)
        timeout = time_to_seconds(timeout)

        self._api_client.execute_procedure(
            "configurationReset", {"removeSiteId": remove_site_id, "removeSecurityCredentials": remove_security_credentials}, timeout)
